```cpp
#include <iostream>
#include <string_view>

void print(int x)              { std::cout << "int " << x << '\n'; }
void print(double x)           { std::cout << "double " << x << '\n'; }
void print(std::string_view s) { std::cout << "text " << s << '\n'; }

int main() {
    print(42);          // exact match: int.
    print(2.5);         // exact match: double.
    print(short{3});    // promotion short -> int: int.
    print(2.5f);        // promotion float -> double: double.
    print("hi");        // converts to string_view: text.
    long n = 7;
    // print(n);        // error: ambiguous (long->int and long->double are both conversions).
    print(static_cast<int>(n));   // explicit choice.
}
```

